suppressPackageStartupMessages({library(edgeR);library(limma);library(AUCell)})
a<-file.path(OUT,'00_input_audit');d<-file.path(OUT,'05_LLPS_ligand_correlation');z<-readRDS(file.path(a,'C5_expression_small.rds'));m<-z$metadata;x<-z$data;counts<-z$counts;focus<-fread(file.path(a,'candidate_overlap.csv'))$gene;db<-CellChatDB.human;lig<-unique(db$interaction$ligand);complex<-db$complex;lig<-unique(c(lig[lig%in%rownames(x)],unlist(complex[intersect(lig,rownames(complex)),,drop=FALSE])));lig<-intersect(lig,rownames(x)[rowSums(x)>0]);genes<-unique(c(intersect(focus,rownames(x)),lig));writecsv(data.table(gene=genes,focus=genes%in%focus,DB_ligand=genes%in%lig),file.path(d,'gene_universe.csv'))
fr<-readRDS(file.path(a,'LLPS77_original_config.rds'));over<-intersect(genes,fr$genes_unique);if(file.exists(file.path(d,'leave_gene_out_scores.csv.gz'))){at<-fread(file.path(d,'leave_gene_out_scores.csv.gz'));at<-at[match(m$cell,cell)];au<-t(as.matrix(at[,setdiff(names(at),'cell'),with=FALSE]))}else{set.seed(123);rankings<-AUCell_buildRankings(x,plotStats=FALSE,verbose=FALSE,nCores=1,BPPARAM=BiocParallel::SerialParam());sets<-c(list(reconstructed_full=fr$genes_unique),setNames(lapply(over,function(g)setdiff(fr$genes_unique,g)),paste0('without_',over)));au<-getAUC(AUCell_calcAUC(sets,rankings,aucMaxRank=fr$aucMaxRank,nCores=1,verbose=FALSE));writecsv(data.table(cell=m$cell,t(au)),file.path(d,'leave_gene_out_scores.csv.gz'));writecsv(data.table(overlap_gene=over),file.path(d,'overlapping_ligands.csv'));writecsv(data.table(Pearson=cor(m$LLPS77_AUC,au[1,]),max_absolute_difference=max(abs(m$LLPS77_AUC-au[1,])),reason='C5-only reconstruction uses fixed seed 123; original chunk-wise tied ranks used seed+chunk. LOO contrasts share reconstructed ranks; original score preserved for primary analysis.'),file.path(d,'score_reconstruction_audit.csv'));rm(rankings);gc(FALSE)}

corfun<-function(a,b,method){if(length(a)<4||sd(a)<1e-8||sd(b)<1e-8)return(c(r=NA_real_,p=NA_real_));ct<-suppressWarnings(cor.test(a,b,method=method,exact=FALSE));c(r=unname(ct$estimate),p=ct$p.value)}
residfun<-function(y,mm){X<-model.matrix(~log1p(nCount_RNA)+log1p(nFeature_RNA),mm);if(nrow(X)-qr(X)$rank<3)return(rep(NA_real_,length(y)));lm.fit(X,y)$residuals}
if(file.exists(file.path(d,'cell_and_specimen_correlations.csv.gz'))){r<-fread(file.path(d,'cell_and_specimen_correlations.csv.gz'))}else{rr<-list();kk<-0L
for(g in genes){v<-as.numeric(x[g,]);for(sensitivity in c('original',if(g%in%over)c('reconstructed_full','leave_gene_out'))){score<-switch(sensitivity,original=m$LLPS77_AUC,reconstructed_full=au[1,],leave_gene_out=au[paste0('without_',g),]);for(scope in c('pooled_tumor',unique(m$specimen_id))){ix<-if(scope=='pooled_tumor')which(m$clinical_group!='Normal')else which(m$specimen_id==scope);mm<-m[ix];sc<-score[ix];vv<-v[ix];hp<-sc>median(sc);lp<-sc<=median(sc);pc<-corfun(sc,vv,'pearson');sp<-corfun(sc,vv,'spearman');rs<-residfun(sc,mm);rv<-residfun(vv,mm);adj<-if(all(is.finite(rs))&&all(is.finite(rv)))corfun(rs,rv,'pearson')else c(r=NA,p=NA);kk<-kk+1L;rr[[kk]]<-data.table(gene=g,sensitivity=sensitivity,scope=scope,patient_id=if(scope=='pooled_tumor')NA_character_ else mm$patient_id[1],dataset=if(scope=='pooled_tumor')'pooled'else mm$dataset[1],clinical_group=if(scope=='pooled_tumor')'Tumor'else mm$clinical_group[1],n_cells=length(ix),pearson=pc[1],spearman=sp[1],adjusted_r=adj[1],pearson_p_descriptive=pc[2],spearman_p_descriptive=sp[2],expression_difference=if(any(hp)&&any(lp))mean(vv[hp])-mean(vv[lp])else NA_real_,detection_difference=if(any(hp)&&any(lp))mean(vv[hp]>0)-mean(vv[lp]>0)else NA_real_)
}}};r<-rbindlist(rr);writecsv(r,file.path(d,'cell_and_specimen_correlations.csv.gz'))}

set.seed(123) # Bootstrap RNG independent of whether AUCell/correlation checkpoints were loaded.
# patient is the independent unit; original within-specimen effects first, then patient median.
pr<-r[scope!='pooled_tumor'&clinical_group!='Normal'&n_cells>=5,lapply(.SD,function(v)if(all(is.na(v)))NA_real_ else median(v,na.rm=TRUE)),by=.(gene,sensitivity,patient_id,dataset),.SDcols=c('pearson','spearman','adjusted_r','expression_difference','detection_difference')];writecsv(pr,file.path(d,'patient_within_specimen_effects.csv.gz'))
stat<-function(v){v<-v[is.finite(v)];n<-length(v);if(!n)return(list(n=0L,median=NA_real_,ci_low=NA_real_,ci_high=NA_real_,p=NA_real_,fraction_positive=NA_real_));ci<-if(n>=5)quantile(matrixStats::colMedians(matrix(sample(v,n*2000,TRUE),nrow=n)),c(.025,.975))else c(NA_real_,NA_real_);list(n=n,median=median(v),ci_low=ci[1],ci_high=ci[2],p=if(n>=5&&any(v!=0))suppressWarnings(wilcox.test(v,mu=0,exact=FALSE)$p.value)else if(n>=5)1 else NA_real_,fraction_positive=mean(v>0))}
long<-melt(pr,id.vars=c('gene','sensitivity','patient_id','dataset'),variable.name='metric');all<-rbindlist(c(list(copy(long)[,stratum:='ALL']),lapply(unique(long$dataset),function(ds)copy(long[dataset==ds])[,stratum:=paste0('dataset:',ds)]),lapply(unique(long$dataset),function(ds)copy(long[dataset!=ds])[,stratum:=paste0('exclude:',ds)])));su<-all[,stat(value),by=.(gene,sensitivity,metric,stratum)];su[,FDR_exploratory:=p.adjust(p,'BH'),by=.(sensitivity,metric,stratum)];su[,FDR_focus:=NA_real_];su[gene%in%focus,FDR_focus:=p.adjust(p,'BH'),by=.(sensitivity,metric,stratum)];writecsv(su,file.path(d,'patient_effect_tests.csv.gz'))
# Raw-count pseudobulk, patient tumor samples combined; normalization uses all expressed genes.
tum<-m[clinical_group!='Normal'];pm<-tum[,.(n_cells=.N,score_mean=mean(LLPS77_AUC),score_median=median(LLPS77_AUC),specimens=uniqueN(specimen_id)),by=.(patient_id,dataset)];pb<-sapply(pm$patient_id,function(p)rowSums(counts[,which(m$patient_id==p&m$clinical_group!='Normal'),drop=FALSE]));rownames(pb)<-rownames(counts);colnames(pb)<-pm$patient_id;atomicRDS(list(counts=pb,metadata=pm),file.path(d,'patient_pseudobulk_small.rds'));writecsv(pm,file.path(d,'patient_pseudobulk_metadata.csv'))
results<-list();express<-list();k<-0L
for(nmin in c(5,10,20)){ok<-which(pm$n_cells>=nmin);mm<-pm[ok];y<-DGEList(pb[,ok,drop=FALSE]);y<-calcNormFactors(y,method='TMM');lc<-round(cpm(y,log=TRUE,prior.count=2),10);express[[as.character(nmin)]]<-data.table(gene=rep(genes,each=nrow(mm)),patient_id=rep(mm$patient_id,length(genes)),logCPM=as.vector(t(lc[genes,,drop=FALSE])),min_cells=nmin)
 for(scope in c('ALL',paste0('dataset:',unique(mm$dataset)),paste0('exclude:',unique(mm$dataset)))){ix<-if(scope=='ALL')seq_len(nrow(mm))else if(startsWith(scope,'dataset:'))which(mm$dataset==sub('dataset:','',scope))else which(mm$dataset!=sub('exclude:','',scope));dd<-mm[ix];if(nrow(dd)<3)next
 for(scoretype in c('score_mean','score_median'))for(g in genes){sv<-dd[[scoretype]];vv<-lc[g,ix];ndet<-sum(pb[g,match(dd$patient_id,colnames(pb))]>0);pc<-corfun(sv,vv,'pearson');sp<-corfun(sv,vv,'spearman');dd$score<-sv;dd$expr<-vv;X<-if(uniqueN(dd$dataset)>1)model.matrix(~score+factor(dataset),dd)else model.matrix(~score,dd);rank<-qr(X)$rank;df<-nrow(X)-rank;beta<-pval<-NA_real_;if(rank==ncol(X)&&df>=3&&sd(sv)>1e-8&&sd(vv)>1e-8&&ndet>=3){fit<-if(uniqueN(dd$dataset)>1)lm(expr~score+factor(dataset),dd)else lm(expr~score,dd);cf<-summary(fit)$coefficients;beta<-cf['score','Estimate'];pval<-cf['score','Pr(>|t|)']};k<-k+1L;results[[k]]<-data.table(gene=g,min_cells=nmin,stratum=scope,score_type=scoretype,n_patients=nrow(dd),gene_detected_patients=ndet,pearson=pc[1],pearson_p=if(nrow(dd)>=5&&ndet>=3)pc[2]else NA_real_,spearman=sp[1],spearman_p=if(nrow(dd)>=5&&ndet>=3)sp[2]else NA_real_,adjusted_beta=beta,adjusted_p=if(nrow(dd)>=5)pval else NA_real_,model_rank=rank,residual_df=df)}
 }}
b<-rbindlist(results);for(pcol in c('pearson_p','spearman_p','adjusted_p')){b[,(paste0(pcol,'_FDR_all')):=p.adjust(get(pcol),'BH'),by=.(min_cells,stratum,score_type)];b[,(paste0(pcol,'_FDR_focus')):=NA_real_];b[gene%in%focus,(paste0(pcol,'_FDR_focus')):=p.adjust(get(pcol),'BH'),by=.(min_cells,stratum,score_type)]};writecsv(b,file.path(d,'pseudobulk_continuous_associations.csv.gz'));writecsv(rbindlist(express),file.path(d,'pseudobulk_ligand_expression.csv.gz'))
# High/low patient paired pseudobulk (within-specimen primary assignments); all tumor specimens pooled within patient/state.
st<-fread(file.path(OUT,'01_LLPS_stratification/cell_assignments.csv.gz'))[method=='within_median'&clinical_group!='Normal'];ps<-st[,.(n_cells=.N),by=.(patient_id,dataset,state)];key<-paste(ps$patient_id,ps$state);pc<-sapply(seq_len(nrow(ps)),function(i)rowSums(counts[,st[patient_id==ps$patient_id[i]&state==ps$state[i],cell],drop=FALSE]));rownames(pc)<-rownames(counts);colnames(pc)<-key
for(nmin in c(5,10,20)){pts<-ps[,.(ok=all(n_cells>=nmin)&&.N==2),by=patient_id][ok==TRUE,patient_id];ii<-which(ps$patient_id%in%pts);if(length(pts)<5){writecsv(data.table(min_cells=nmin,patients=length(pts),status='Insufficient patients (<5)'),file.path(d,paste0('paired_pseudobulk_status_',nmin,'.csv')));next};dd<-ps[ii];dd$state<-factor(dd$state,levels=c('low','high'));design<-model.matrix(~factor(patient_id)+state,dd);y<-DGEList(pc[,ii,drop=FALSE]);keep<-filterByExpr(y,design=design);y<-calcNormFactors(y[keep,,keep.lib.sizes=FALSE]);v<-voom(y,design,plot=FALSE);fit<-eBayes(lmFit(v,design));tt<-as.data.table(topTable(fit,coef='statehigh',number=Inf,sort.by='none'),keep.rownames='gene');tt[,min_cells:=nmin];tt[,FDR_focus:=NA_real_];tt[gene%in%focus,FDR_focus:=p.adjust(P.Value,'BH')];writecsv(tt,file.path(d,paste0('paired_pseudobulk_voom_',nmin,'.csv.gz')))}
